@Composable
private fun ThreadReactionChip(
    reaction: KuiklyThreadReactionItem,
    interactionIdentity: Any = "reaction:${reaction.emoji}",
    loading: Boolean = false,
    onClick: (() -> Unit)? = null,
    onLongPress: ((SlockPopoverAnchor) -> Unit)? = null
) {
    val currentOnClick by rememberUpdatedState(onClick.takeUnless { loading })
    val currentOnLongPress by rememberUpdatedState(onLongPress)
    val hoverInteractionSource = remember(interactionIdentity) { MutableInteractionSource() }
    val isHovered by hoverInteractionSource.collectIsHoveredAsState()
    val background = threadReactionChipBackground(reaction.selected, emphasized = isHovered)
    val chipModifier =
        Modifier
            .hoverable(hoverInteractionSource)
            .background(background, RoundedCornerShape(SlockRadius.Sm))
            .padding(horizontal = 6.dp, vertical = 3.dp)
    val chipContent: @Composable () -> Unit = {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            ThreadQuickReactionGlyph(threadDisplayReactionEmoji(reaction.emoji), modifier = Modifier.size(15.dp))
            if (reaction.count > 0) {
                Text(
                    text = reaction.count.toString(),
                    style = SlockType.Caption.withSlockFontWeight(FontWeight.Bold).copy(fontSize = 12.sp, lineHeight = 14.sp),
                    color = SlockColor.TextBlack,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
            if (onClick != null || loading) {
                Box(
                    modifier = Modifier.size(12.dp),
                    contentAlignment = Alignment.Center
                ) {
                    if (loading) {
                        SlockChipLoadingIndicator(size = 12.dp)
                    }
                }
            }
        }
    }
    if (onLongPress != null) {
        // task #569: tap keeps toggling the reaction; long-press surfaces the
        // reactor tooltip. Both live on one gesture detector so the long
        // press cannot fire a toggle. The anchor is reported in root pixels
        // (same contract as the message long-press menu).
        val rootAnchor =
            remember(interactionIdentity) { SlockLiveRootAnchorRef(identity = interactionIdentity) }
        Box(
            modifier = Modifier
                .slockCaptureLiveRootAnchor(rootAnchor)
                .pointerInput(interactionIdentity, onClick != null) {
                    detectTapGestures(
                        onTap = { currentOnClick?.invoke() },
                        onLongPress = { localOffset ->
                            rootAnchor.resolve(SlockPopoverLocalPoint.Exact(localOffset))?.let { anchor ->
                                currentOnLongPress?.invoke(anchor)
                            }
                        }
                    )
                }
                .then(chipModifier),
            contentAlignment = Alignment.Center
        ) {
            chipContent()
        }
    } else if (onClick != null && !loading) {
        Button(onClick = onClick, pressFeedback = false) {
            Box(
                modifier = chipModifier,
                contentAlignment = Alignment.Center
            ) {
                chipContent()
            }
        }
    } else {
        Box(
            modifier = chipModifier,
            contentAlignment = Alignment.Center
        ) {
            chipContent()
        }
    }
}

internal fun threadNeutralMessageSurfaceColor(emphasized: Boolean): Color =
    SlockColor.TextBlack.copy(alpha = if (emphasized) 0.08f else 0.03f)

internal fun threadReactionChipBackground(
    selected: Boolean,
    emphasized: Boolean = false
): Color =
    if (selected) {
        SlockColor.AccentPink.copy(alpha = 0.2f)
    } else {
        threadNeutralMessageSurfaceColor(emphasized)
    }

internal fun threadReactionAddChipBackground(emphasized: Boolean = false): Color =
    threadNeutralMessageSurfaceColor(emphasized)

// task #569: everything the tooltip needs, captured at long-press time.
internal data class ThreadReactionDetailsRequest(
    val emoji: String,
    val names: List<String>,
    val count: Int,
    val anchor: SlockPopoverAnchor
)

// Label formatting for the reactor tooltip: first N names + "+K" for the
// rest (mobile pendant of the web hover tooltip). Falls back to a bare count
// when the payload carries no names (older servers).
internal fun threadReactionDetailsLabel(
    names: List<String>,
    count: Int,
    maxNames: Int = ThreadReactionDetailsMaxNames
): String {
    val clean = names.map { it.trim() }.filter { it.isNotBlank() }.distinct()
    if (clean.isEmpty()) {
        return if (count == 1) "1 person" else "$count people"
    }
    val shown = clean.take(maxNames)
    val hidden = maxOf(count, clean.size) - shown.size
    val joined = shown.joinToString(", ")
    return if (hidden > 0) "$joined +$hidden" else joined
}

internal const val ThreadReactionDetailsMaxNames = 4

