private enum class ThreadForwardSelectionMode(val wireValue: String, val label: String) {
    Merged("merged", "Merged"),
    Individual("individual", "Individual")
}

private fun ThreadForwardSelectionMode.toForwardMessageSendMode(): ForwardMessageSendMode =
    when (this) {
        ThreadForwardSelectionMode.Merged -> ForwardMessageSendMode.Merged
        ThreadForwardSelectionMode.Individual -> ForwardMessageSendMode.Individual
    }

internal data class ThreadForwardOutcome(
    val failureCode: String? = null
)

internal fun ForwardMessageTarget.threadForwardSelectionKey(): String = "${serverId.value}:${kind.name}:$id"

internal fun List<ForwardMessageTarget>.threadForwardPickerTargets(
    sourceServerId: ServerId?,
    sourceChannelId: ChannelId?
): List<ForwardMessageTarget> =
    filterNot { target ->
        sourceServerId != null &&
            sourceChannelId != null &&
            target.serverId == sourceServerId &&
            target.channelId == sourceChannelId
    }

internal suspend fun executeThreadForward(
    repository: ForwardMessageTargetRepository,
    liveSourceServerId: ServerId?,
    sourceChannelId: ChannelId,
    receipt: ThreadForwardDestinationReceipt,
    currentDirectoryGeneration: Int,
    messageIds: List<String>,
    mode: ForwardMessageSendMode,
    note: String
): ThreadForwardOutcome {
    // task #803: the send consumes ONLY the tap-time frozen receipt. The gate
    // compares the frozen source against the LIVE server authority read at
    // confirm time (never the frozen picker-open value — LiBai's blocker 1);
    // resolve and the wire request then run against the FROZEN source. Any
    // drift (server switch, directory refresh, identity tamper) fails typed
    // with ZERO forward API traffic — never forward elsewhere.
    receipt.preResolveFailureCode(
        liveSourceServerId = liveSourceServerId,
        currentDirectoryGeneration = currentDirectoryGeneration
    )?.let { return ThreadForwardOutcome(failureCode = it) }
    val frozenSourceServerId = receipt.sourceServerId
    val target = receipt.target
    val resolved = repository.resolveTargetChannel(frozenSourceServerId, target)
    val destination =
        when (resolved) {
            is DataResult.Content -> resolved.data
            else ->
                return ThreadForwardOutcome(
                    failureCode = resolved.threadForwardFailureCode("forward_target_unavailable")
                )
        }
    receipt.postResolveFailureCode(destination)?.let {
        return ThreadForwardOutcome(failureCode = it)
    }
    if (destination.serverId == frozenSourceServerId && destination.channelId == sourceChannelId) {
        return ThreadForwardOutcome(failureCode = "forward_source_target_forbidden")
    }
    val forwarded =
        repository.forwardMessages(
            ForwardMessageExecuteRequest(
                sourceServerId = frozenSourceServerId,
                sourceChannelId = sourceChannelId,
                destination = destination,
                messageIds = messageIds,
                mode = mode,
                note = note
            )
        )
    return if (forwarded is DataResult.Content) {
        ThreadForwardOutcome()
    } else {
        ThreadForwardOutcome(failureCode = forwarded.threadForwardFailureCode("forward_failed"))
    }
}

private fun DataResult<*>.threadForwardFailureCode(fallback: String): String =
    when (this) {
        is DataResult.Content -> fallback
        is DataResult.Empty -> "forward_no_selected_messages"
        is DataResult.Error -> error.code
        is DataResult.NoPermission -> blocker.code
    }

private fun String?.threadForwardSelectionModeLabel(): String =
    when (this?.trim()?.lowercase()) {
        ThreadForwardSelectionMode.Individual.wireValue -> ThreadForwardSelectionMode.Individual.label
        else -> ThreadForwardSelectionMode.Merged.label
    }

private data class ThreadForwardTargetLoadPage(
    val items: List<ForwardMessageTarget>,
    val nextCursor: ForwardMessageTargetDirectoryCursor? = null,
    val reset: Boolean = false
)

internal fun ForwardMessageTarget.toSlockForwardTargetPickerItem(): SlockForwardTargetPickerItem<ForwardMessageTarget> =
    SlockForwardTargetPickerItem(
        stableKey = threadForwardSelectionKey(),
        title = title,
        subtitle = threadForwardTargetSubtitle(),
        avatarWireValue = avatarWireValue,
        avatarLabel = avatarLabel,
        visualKind = forwardTargetVisualKind(),
        payload = this
    )

internal fun ForwardMessageTarget.forwardTargetVisualKind(): SlockForwardTargetVisualKind =
    when {
        kind == ForwardMessageTargetKind.RecentDirectMessage ||
            kind == ForwardMessageTargetKind.HumanDirectMessageCandidate ||
            kind == ForwardMessageTargetKind.AgentDirectMessageCandidate ->
            SlockForwardTargetVisualKind.DirectMessage
        channelKind == ConversationKind.Joint || channelType?.trim()?.lowercase() == "joint" ->
            SlockForwardTargetVisualKind.JointChannel
        channelType?.trim()?.lowercase() == "private" ->
            SlockForwardTargetVisualKind.PrivateChannel
        else -> SlockForwardTargetVisualKind.PublicChannel
    }

private fun ForwardMessageTarget.threadForwardTargetSubtitle(): String =
    when (requiredAction) {
        ForwardMessageTargetRequiredAction.JoinChannel ->
            subtitle.ifBlank { "Join channel before forwarding" }
        ForwardMessageTargetRequiredAction.CreateDirectMessage ->
            subtitle.ifBlank { "Start DM before forwarding" }
        ForwardMessageTargetRequiredAction.None ->
            subtitle.ifBlank {
                when (kind) {
                    ForwardMessageTargetKind.RecentChannel -> "Recent channel"
                    ForwardMessageTargetKind.RecentDirectMessage -> "Recent DM"
                    ForwardMessageTargetKind.PublicChannelUnjoined -> "Public channel"
                    ForwardMessageTargetKind.HumanDirectMessageCandidate -> "Member"
                    ForwardMessageTargetKind.AgentDirectMessageCandidate -> "Agent"
                }
            }
    }

@Composable
private fun <T> SlockForwardTargetPickerItem<T>.localizedForwardTargetSubtitle(): String =
    when (subtitle) {
        "Join channel before forwarding" -> stringResource(MR.strings.thread_forward_join_channel_first)
        "Start DM before forwarding" -> stringResource(MR.strings.thread_forward_start_dm_first)
        "Recent channel" -> stringResource(MR.strings.thread_forward_recent_channel)
        "Recent DM" -> stringResource(MR.strings.thread_forward_recent_dm)
        "Public channel" -> stringResource(MR.strings.thread_forward_public_channel)
        "Member" -> stringResource(MR.strings.thread_forward_member)
        "Agent" -> stringResource(MR.strings.thread_forward_agent)
        else -> subtitle
    }

